# Generated by build.py from recipe.yml for recipe smtp-keep-mail-across-restarts. Do not edit.
set -e
cd "$(dirname "$0")"
mkdir -p data
cat > order.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 1042 has shipped

Your order is on its way.
EOF
cat > later.eml <<'EOF'
From: shop@example.com
To: ann@example.com
Subject: Order 1043 has shipped

Your second order is on its way.
EOF
printf '%s\n' 'the server'\''s data directory' > data/readme.txt
surl --directory data --mail-domain example.com --mailbox shop@example.com:shoppass --mailbox ann@example.com:annpass smtp://127.0.0.1:8080/ imap://127.0.0.1:8081/ &
sleep 1
curl -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8080/example.com --next -sS --crlf -u shop@example.com:shoppass --mail-from shop@example.com --mail-rcpt ann@example.com -T order.eml smtp://127.0.0.1:8082/example.com
curl -sS --retry 10 --retry-all-errors --retry-delay 1 -o /dev/null -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1" --next -sS --retry 10 --retry-all-errors --retry-delay 1 -o /dev/null -u ann@example.com:annpass "imap://127.0.0.1:8083/INBOX;UID=1"
curl -sS -u ann@example.com:annpass -X "STORE 1 +FLAGS \Flagged" imap://127.0.0.1:8081/INBOX
curl -sS -u ann@example.com:annpass "imap://127.0.0.1:8081/INBOX;UID=1;SECTION=TEXT"
kill $(jobs -p)
